```js
// equivalent pure functions
function double(x) { return x * 2; }         // declaration (hoisted)
const double2 = function (x) { return x * 2; }; // expression
const double3 = (x) => x * 2;                  // arrow, implicit return

class Timer {
  seconds = 0;
  start() {
    setInterval(() => { this.seconds++; }, 1000);   // arrow: this = the Timer
  }
}

const counter = {
  n: 0,
  increment() { this.n++; },       // method syntax: this = counter
};
```

| Form | Own `this`? | Hoisted? | Constructor? |
|---|---|---|---|
| declaration. | yes. | yes. | yes. |
| expression. | yes. | no. | yes. |
| arrow. | **no** (uses outer). | no. | no. |
| method shorthand. | yes. | — | no. |

